CREATE TABLE IF NOT EXISTS users(id CHAR(32) PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('teacher','student') NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS classes(id CHAR(32) PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS class_memberships(user_id CHAR(32) NOT NULL,class_id CHAR(32) NOT NULL,PRIMARY KEY(user_id,class_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions(id CHAR(64) PRIMARY KEY,user_id CHAR(32) NOT NULL,csrf_token VARCHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS materials(id CHAR(32) PRIMARY KEY,class_id CHAR(32) NOT NULL,uploader_id CHAR(32) NOT NULL,filename VARCHAR(255) NOT NULL,type ENUM('txt','md') NOT NULL,size_bytes INT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(uploader_id) REFERENCES users(id),CHECK(size_bytes>0 AND size_bytes<=10485760),INDEX(class_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS material_contents(material_id CHAR(32) PRIMARY KEY,body LONGTEXT NOT NULL,original LONGBLOB NOT NULL,FOREIGN KEY(material_id) REFERENCES materials(id) ON DELETE CASCADE,CHECK(CHAR_LENGTH(TRIM(body))>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seed_versions(version INT PRIMARY KEY,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
